dashboard.definition:
{
    "title": "Medical Technology and IoT",
    "description": "Medical devices: connection, status and alarms by device class, MRI helium and temperatures, STK/MTK from asset management",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_dept": {
            "type": "input.dropdown",
            "title": "Department",
            "options": {
                "items": [
                    {
                        "label": "All departments",
                        "value": "*"
                    },
                    {
                        "label": "Internal Medicine (INN)",
                        "value": "INN"
                    },
                    {
                        "label": "Cardiology (KAR)",
                        "value": "KAR"
                    },
                    {
                        "label": "Neurology (NEU)",
                        "value": "NEU"
                    },
                    {
                        "label": "Oncology (ONK)",
                        "value": "ONK"
                    },
                    {
                        "label": "General Surgery (CHI)",
                        "value": "CHI"
                    },
                    {
                        "label": "Trauma Surgery/Orthopedics (UCH)",
                        "value": "UCH"
                    },
                    {
                        "label": "Urology (URO)",
                        "value": "URO"
                    },
                    {
                        "label": "HNO",
                        "value": "HNO"
                    },
                    {
                        "label": "Anesthesia/OR (ANA)",
                        "value": "ANA"
                    },
                    {
                        "label": "Intensive Care (ICU)",
                        "value": "ICU"
                    },
                    {
                        "label": "Emergency Department (ZNA)",
                        "value": "ZNA"
                    },
                    {
                        "label": "Radiology (RAD)",
                        "value": "RAD"
                    },
                    {
                        "label": "Gynecology/Obstetrics (GYN)",
                        "value": "GYN"
                    },
                    {
                        "label": "Pediatrics (PAED)",
                        "value": "PAED"
                    },
                    {
                        "label": "Psychiatry (PSY)",
                        "value": "PSY"
                    }
                ],
                "token": "dept",
                "defaultValue": "*"
            }
        },
        "input_building": {
            "type": "input.dropdown",
            "title": "Building",
            "options": {
                "items": [
                    {
                        "label": "All buildings",
                        "value": "*"
                    },
                    {
                        "label": "Building A - Internal Medicine",
                        "value": "A"
                    },
                    {
                        "label": "Building B - Surgical Center",
                        "value": "B"
                    },
                    {
                        "label": "Building C - Acute and Intensive Care Center",
                        "value": "C"
                    },
                    {
                        "label": "Building D - Women, Children and Mental Health",
                        "value": "D"
                    }
                ],
                "token": "building",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "device": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_latest": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:medtech:telemetry\" department=\"$dept$\" building=\"$building$\" earliest=-20m\n| stats latest(device_class) as device_class latest(device_type) as device_type latest(manufacturer) as manufacturer latest(model) as model latest(status) as status latest(connectivity) as connectivity latest(alarm_count) as alarms latest(ward) as ward latest(building) as building latest(department) as department by device_id",
                "enableSmartSources": true
            },
            "name": "Device status"
        },
        "ds_k_total": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| stats count as Devices"
            }
        },
        "ds_k_online": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| stats count(eval(connectivity=\"online\")) as on count as n | eval \"Online %\"=round(100 * on / n, 1) | fields \"Online %\""
            }
        },
        "ds_k_offline": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| where connectivity!=\"online\" | stats count as Offline"
            }
        },
        "ds_k_alarms": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| stats sum(alarms) as \"Active alarms\""
            }
        },
        "ds_k_he": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.mri.helium_level_pct\" device_id=\"MRT-1\" span=5m | rename v as \"MRT-1 Helium\"",
                "enableSmartSources": true
            }
        },
        "ds_k_stk": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"snow:alm_asset\" model_category=\"Medical Technology\" earliest=-7h | stats latest(u_stk_days_left) as d by asset_tag | where d<0 | stats count as \"STK overdue\"",
                "enableSmartSources": true
            }
        },
        "ds_imaging": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:medtech:telemetry\" device_type IN (\"MRT\", \"CT\") earliest=-10m\n| stats latest(device_type) as device_type latest(manufacturer) as manufacturer latest(model) as model latest(status) as status latest(helium_level_pct) as helium_level_pct latest(magnet_temp_k) as magnet_temp_k latest(shield_temp_k) as shield_temp_k latest(cold_head_status) as cold_head_status latest(tube_heat_pct) as tube_heat_pct latest(exams_today) as exams_today latest(scans_today) as scans_today by device_id\n| eval exams_today=coalesce(exams_today, scans_today)",
                "enableSmartSources": true
            },
            "name": "Scanners"
        },
        "ds_he": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.mri.helium_level_pct\" BY device_id span=5m\n| timechart span=5m avg(v) by device_id",
                "enableSmartSources": true
            },
            "name": "MRI helium level"
        },
        "ds_shield": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_en_metrics metric_name IN (\"sakh.mri.shield_temp_k\", \"sakh.mri.compressor_water_temp_c\") device_id=\"$device$\" BY metric_name device_id span=5m\n| eval series=device_id.\" \".if(metric_name=\"sakh.mri.shield_temp_k\", \"Shield K\", \"Cooling water °C\") | timechart span=5m avg(v) by series",
                "enableSmartSources": true
            }
        },
        "ds_class": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| eval state=if(connectivity!=\"online\", \"Offline\", if(alarms>0, \"Alarm\", status))\n| chart count over device_class by state"
            }
        },
        "ds_online_trend": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.medtech.online\" department=\"$dept$\" building=\"$building$\" BY building span=10m\n| eval v=round(100 * v, 1), building=\"Building \".building | timechart span=10m avg(v) by building",
                "enableSmartSources": true
            }
        },
        "ds_offline": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_latest",
                "query": "| where connectivity!=\"online\" OR alarms>0\n| table device_id device_class manufacturer model building ward status connectivity alarms\n| rename device_id as Device device_class as Class manufacturer as Manufacturer model as Model building as Building ward as Ward status as Status connectivity as Connection alarms as Alarms"
            }
        },
        "ds_stk": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"snow:alm_asset\" model_category=\"Medical Technology\" u_department=\"$dept$\" earliest=-7h\n| stats latest(display_name) as Device latest(model) as Model latest(manufacturer) as Manufacturer latest(u_stk_due) as \"STK due\" latest(u_stk_days_left) as \"Days\" latest(u_mtk_due) as \"MTK due\" latest(u_stk_status) as Status latest(u_department) as Department by asset_tag\n| where Days < 45 | sort Days | fields - asset_tag",
                "enableSmartSources": true
            }
        },
        "ds_alarm_trend": {
            "type": "ds.search",
            "options": {
                "query": "| mstats sum(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.medtech.alarm_count\" department=\"$dept$\" building=\"$building$\" BY device_type span=15m\n| timechart span=15m sum(v) by device_type",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_care.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_beds",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_diag": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_diag.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_lab",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_medtech": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_medtech_on.svg",
                "preserveAspectRatio": true
            }
        },
        "viz_nav_network": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_network.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_network",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_it": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_it.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_servers",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_security": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_security.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_security",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_total"
            },
            "options": {
                "majorColor": "#2f6fc4",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_online"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#0b7fab",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 90,
                        "value": "#c8253f"
                    },
                    {
                        "from": 90,
                        "to": 98,
                        "value": "#c98a00"
                    },
                    {
                        "from": 98,
                        "value": "#1e8a5a"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_offline"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 1,
                        "to": 10,
                        "value": "#c98a00"
                    },
                    {
                        "from": 10,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_alarms"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 5,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 5,
                        "to": 15,
                        "value": "#c98a00"
                    },
                    {
                        "from": 15,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_he"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#0b7fab",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 70,
                        "value": "#c8253f"
                    },
                    {
                        "from": 70,
                        "to": 80,
                        "value": "#c98a00"
                    },
                    {
                        "from": 80,
                        "value": "#1e8a5a"
                    }
                ]
            }
        },
        "viz_06": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_stk"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 1,
                        "to": 5,
                        "value": "#c98a00"
                    },
                    {
                        "from": 5,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_07": {
            "type": "kis_clinic.imaging_status",
            "dataSources": {
                "primary": "ds_imaging"
            },
            "options": {
                "drilldownToken": "device"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "device",
                                "key": "value"
                            }
                        ]
                    }
                }
            ]
        },
        "viz_08": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_he"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#0b7fab",
                    "#6b4fb3",
                    "#1e8a5a",
                    "#c98a00",
                    "#c8253f",
                    "#2f6fc4",
                    "#b8457c",
                    "#0f8f84",
                    "#d0661f",
                    "#9b3fae"
                ],
                "yAxisMin": 50,
                "yAxisMax": 100,
                "lineWidth": 2
            }
        },
        "viz_09": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_shield"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#0b7fab",
                    "#6b4fb3",
                    "#1e8a5a",
                    "#c98a00",
                    "#c8253f",
                    "#2f6fc4",
                    "#b8457c",
                    "#0f8f84",
                    "#d0661f",
                    "#9b3fae"
                ],
                "lineWidth": 2
            }
        },
        "viz_10": {
            "type": "splunk.column",
            "dataSources": {
                "primary": "ds_class"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#1e8a5a",
                    "#c98a00",
                    "#c8253f",
                    "#0b7fab",
                    "#6b4fb3",
                    "#2f6fc4"
                ],
                "stackMode": "stacked"
            }
        },
        "viz_11": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_online_trend"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#0b7fab",
                    "#6b4fb3",
                    "#1e8a5a",
                    "#c98a00",
                    "#c8253f",
                    "#2f6fc4",
                    "#b8457c",
                    "#0f8f84",
                    "#d0661f",
                    "#9b3fae"
                ],
                "yAxisMin": 0,
                "yAxisMax": 100,
                "lineWidth": 2
            }
        },
        "viz_12": {
            "type": "splunk.column",
            "dataSources": {
                "primary": "ds_alarm_trend"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#0b7fab",
                    "#6b4fb3",
                    "#1e8a5a",
                    "#c98a00",
                    "#c8253f",
                    "#2f6fc4",
                    "#b8457c",
                    "#0f8f84",
                    "#d0661f",
                    "#9b3fae"
                ],
                "stackMode": "stacked"
            }
        },
        "viz_13": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_offline"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 10,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#e9eef4",
                    "rowColors": "#13294b",
                    "headerColor": "#5b6878"
                },
                "columnFormat": {
                    "Status": {
                        "rowBackgroundColors": "> table | seriesByName(\"Status\") | matchValue(statusBg)"
                    },
                    "Connection": {
                        "rowBackgroundColors": "> table | seriesByName(\"Connection\") | matchValue(statusBg)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#ffffff",
                    "#f5f7fa"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "Degraded",
                        "value": "#fcefcc"
                    },
                    {
                        "match": "Healthy",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "critical",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "high",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "error",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "warning",
                        "value": "#fcefcc"
                    },
                    {
                        "match": "medium",
                        "value": "#fcefcc"
                    },
                    {
                        "match": "stopped",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "failed",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "running",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "success",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "good",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "normal",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "Reachable",
                        "value": "#d9f0e3"
                    },
                    {
                        "match": "Unreachable",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "critical",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "full",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "stopped",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "Blocked",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "Offline",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "Failed",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "Error",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "Vulnerable",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "overdue",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "escalated to attending physician",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "2nd escalation: attending on duty",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "not yet communicated",
                        "value": "#f9dde1"
                    },
                    {
                        "match": "communicated by phone",
                        "value": "#fcefcc"
                    },
                    {
                        "match": "queued",
                        "value": "#fcefcc"
                    },
